// Native LiftBridge04 upper tower shells; generated by Lift04UpperShells.py.
// Bone 0, original Y/Z and triangle connectivity are preserved.
using System;
using UnityEngine;

namespace BridgeBuilder.Bridges;

internal static class Lift04UpperShells
{
    internal static void Apply(int lod, Vector3[] source, Vector3[] positions, float delta)
    {
        var data = lod switch
        {
            0 => (Count: 60636, Parts: Level0),
            1 => (Count: 45780, Parts: Level1),
            2 => (Count: 3212, Parts: Level2),
            _ => throw new ArgumentOutOfRangeException(nameof(lod))
        };
        if (source.Length != data.Count || positions.Length != data.Count || !float.IsFinite(delta))
            throw new InvalidOperationException("Lift04 upper tower shells requires its recorded native topology.");
        foreach (var part in data.Parts)
            for (var i = part.First; i <= part.Last; i++)
                positions[i].x = source[i].x + part.Sign * delta;
    }

